/*--------------------------------------------------------------------termio.h-*//*	termio.h - header file for programs using termio.c	pwf - Thu Aug  3 12:05:27 1989	All I/O with the terminal is done here. All output to the terminal is 	buffered internally. It is assured, that all output has been sent before 	an input is started.	The global routines are :		void ttopen()		- opens the terminal channel		void ttclose()		- flush and close the terminal channel		void ttflush()		- clears all buffers to the terminal		void ttputc(c)		- writes one character 'c'		void ttputsn(s,n)	- writes the string 's' length 'n'		void ttputs(s)		- write the string s with zero termination		int  ttgetc()		- gets a character from the terminal		int  ttgets(s)		- gets a string, returns numbr of chars read		int  ttgetsn(s,n)	- gets a string max.len. 'n', returns number of chars		int  keypressed()   - returns number of input chars in buffer*//*-----------------------------------------------------------------------------*/extern void ttopen();extern void ttclose();extern void ttflush();extern void ttputc();extern void ttputs();extern void ttputsn();extern int	ttgetc();extern int  ttgets();extern int  ttgetsn();extern int  keypressed();/*--------------------------------------------------------------------termio.h-*/